def max_sum(arr):
    n = len(arr)
    # Initialize the max sum
    max_sum = 0

    for i in range(n):
        # Find the longest increasing subsequence ending at arr[i]
        inc = [arr[i]]
        for j in range(i, n):
            if arr[j] > arr[j-1]:
                inc.append(arr[j])
            else:
                break
        # Find the longest decreasing subsequence starting at the end of the increasing subsequence
        dec = inc[::-1]
        for j in range(len(inc)-2, -1, -1):
            if dec[j] > dec[j+1]:
                dec[j] = dec[j+1]
            else:
                break
        # Calculate the sum of the bitonic subsequence
        for j in range(len(dec)):
            max_sum = max(max_sum, sum(dec[:j+1]))

    return max_sum

