            return False
        a, b = 1, 2
        for _ in range(n):
            a, b = b, 2*b + a
            if not isprime(b):
                return False
        return True

    def newman_prime(n):
        count = 0
        for prime in primerange(1, 10000):  # Assuming the nth NSW prime is within this range for simplicity
            if is_nsw_prime(prime):
                count += 1
                if count == n:
                    return prime
        return -1  # This should never happen if the range is large enough

    return newman_prime(n)

