def rearrange_bigger(n):
    if n < 10:
        return False

    def swap_digits(num, i, j):
        num_list = list(str(num))
        num_list[i], num_list[j] = num_list[j], num_list[i]
        return int(''.join(num_list))

    def find_next_bigger(num):
        if num < 10:
            return None
        for i in range(len(str(num)) - 1):
            if str(num)[i] < str(num)[i + 1]:
                return swap_digits(num, i, i + 1)
        return None

    next_bigger = find_next_bigger(n)
    return next_bigger if next_bigger is not None else False

